def estimate_tokens(text):
    chinese = sum(1 for ch in text if '\u4e00' <= ch <= '\u9fff')
    other = len(text) - chinese
    return int(chinese * 1.25 + other * 0.75)

print(estimate_tokens("胸腔镜肺叶切除术后的并发症分析"))
