import json

# 模板：一篇文献的 8 个字段
template = {"论文名称": "", "作者": "", "杂志名称": "", "年份": "",
            "卷": "", "期": "", "页": "", "关键词": ""}

def add_paper(papers):
    paper = {}
    paper["论文名称"] = input("论文名称：")
    paper["作者"] = input("作者：")
    papers.append(paper)
    print(f"已添加：{paper['论文名称']}")

def show_all(papers):
    for i, paper in enumerate(papers, 1):
        print(f"{i}. {paper['论文名称']} ({paper['作者']})")

def save_to_file(papers):
    with open("papers.json", "w", encoding="utf-8") as f:
        json.dump(papers, f, ensure_ascii=False, indent=2)

def load_from_file():
    with open("papers.json", "r", encoding="utf-8") as f:
        return json.load(f)

# 主程序：加载 → 添加 → 显示 → 保存
db = load_from_file()
add_paper(db)
show_all(db)
save_to_file(db)

